 (DI, "शाखाओं A, C और F द्वारा अस्वीकृत आवेदनों की संयुक्त संख्या, इन्हीं शाखाओं द्वारा प्राप्त कुल आवेदनों का कौन-सा अंश (भिन्न) है?", ["4/5", "1/4", "3/4", "2/5"], 1,
  "अस्वीकृत: A = 480−360 = 120, C = 720−540 = 180, F = 1000−750 = 250 ⇒ 550\nप्राप्त: 480 + 720 + 1000 = 2200\nअंश = 550/2200 = 1/4", "", "", D3),
 (DI, "यदि शाखा C में 60 अतिरिक्त आवेदन स्वीकृत हो जाते हैं, जबकि प्राप्त आवेदनों की कुल संख्या अपरिवर्तित रहती है, तो शाखा C में स्वीकृत और अस्वीकृत आवेदनों का संशोधित अनुपात क्या होगा?", ["6 : 1", "7 : 1", "4 : 1", "5 : 1"], 3,
  "C: स्वीकृत = 540 + 60 = 600, अस्वीकृत = 720 − 600 = 120\nअनुपात = 600 : 120 = 5 : 1", "", "", D3),
 (DI, "शाखाओं A, C और F द्वारा स्वीकृत आवेदनों की औसत संख्या का शाखाओं A, B और C द्वारा प्राप्त आवेदनों की औसत संख्या से अनुपात क्या है?", ["14 : 15", "11 : 12", "13 : 14", "12 : 13"], 1,
  "स्वीकृत औसत (A,C,F) = (360 + 540 + 750)/3 = 1650/3 = 550\nप्राप्त औसत (A,B,C) = (480 + 600 + 720)/3 = 1800/3 = 600\nअनुपात = 550 : 600 = 11 : 12", "", "", D3),
 (DI, "यदि शाखा C में स्वीकृत आवेदनों की संख्या में एक-छठे भाग की वृद्धि होती है और शाखा E में स्वीकृत आवेदनों की संख्या में एक-छठे भाग की कमी होती है, जबकि प्राप्त आवेदनों की संख्या अपरिवर्तित रहती है, तो शाखा C में संशोधित अस्वीकृत आवेदनों का शाखा E में संशोधित अस्वीकृत आवेदनों से अनुपात क्या है?", ["1 : 4", "3 : 10", "6 : 7", "2 : 5"], 1,
  "C: स्वीकृत = 540 × 7/6 = 630 ⇒ अस्वीकृत = 720 − 630 = 90\nE: स्वीकृत = 720 × 5/6 = 600 ⇒ अस्वीकृत = 900 − 600 = 300\nअनुपात = 90 : 300 = 3 : 10", "", "", D3),
 (DI, "शाखाओं B और E द्वारा स्वीकृत आवेदनों की संयुक्त संख्या, इन्हीं शाखाओं द्वारा प्राप्त आवेदनों की कुल संख्या का कितने प्रतिशत है?", ["85%", "80%", "75%", "70%"], 1,
  "स्वीकृत = 480 + 720 = 1200; प्राप्त = 600 + 900 = 1500\nप्रतिशत = 1200/1500 × 100 = 80%", "", "", D3),
 (DI, "स्टोरों P और Q द्वारा बेची गई इकाइयों की कुल संख्या का स्टोर T द्वारा बेची गई इकाइयों की संख्या से अनुपात क्या है?", ["9 : 8", "6 : 5", "7 : 6", "8 : 7"], 2,
  "P + Q = 360 + 480 = 840; T = 720\nअनुपात = 840 : 720 = 7 : 6", "", "", D4),
